module adder_pipe_64bit(
    input clk, 
    input rst_n, 
    input i_en, 
    input [63:0] adda, 
    input [63:0] addb, 
    output [64:0] result, 
    output o_en
);
// Internal registers for pipeline stages
reg [63:0] adda_reg [0:7];
reg [63:0] addb_reg [0:7];
reg [64:0] result_reg [0:7];
reg [6:0] carry_in_reg [0:7];
reg o_en_reg [0:7];
// Pipeline stage 1
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[0] <= 64'd0;
        addb_reg[0] <= 64'd0;
        result_reg[0] <= 65'd0;
        carry_in_reg[0] <= 7'd0;
        o_en_reg[0] <= 1'b0;
    end else begin
        adda_reg[0] <= adda;
        addb_reg[0] <= addb;
        result_reg[0] <= adda_reg[0] + addb_reg[0] + carry_in_reg[0][0];
        carry_in_reg[0][1] <= result_reg[0][64];
        o_en_reg[0] <= i_en;
    end
end
// Pipeline stage 2
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[1] <= 64'd0;
        addb_reg[1] <= 64'd0;
        result_reg[1] <= 65'd0;
        carry_in_reg[1] <= 7'd0;
        o_en_reg[1] <= 1'b0;
    end else begin
        adda_reg[1] <= adda_reg[0];
        addb_reg[1] <= addb_reg[0];
        result_reg[1] <= adda_reg[1] + addb_reg[1] + carry_in_reg[1][0];
        carry_in_reg[1][1] <= result_reg[1][64];
        o_en_reg[1] <= o_en_reg[0];
    end
end
// Pipeline stage 3
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[2] <= 64'd0;
        addb_reg[2] <= 64'd0;
        result_reg[2] <= 65'd0;
        carry_in_reg[2] <= 7'd0;
        o_en_reg[2] <= 1'b0;
    end else begin
        adda_reg[2] <= adda_reg[1];
        addb_reg[2] <= addb_reg[1];
        result_reg[2] <= adda_reg[2] + addb_reg[2] + carry_in_reg[2][0];
        carry_in_reg[2][1] <= result_reg[2][64];
        o_en_reg[2] <= o_en_reg[1];
    end
end
// Pipeline stage 4
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[3] <= 64'd0;
        addb_reg[3] <= 64'd0;
        result_reg[3] <= 65'd0;
        carry_in_reg[3] <= 7'd0;
        o_en_reg[3] <= 1'b0;
    end else begin
        adda_reg[3] <= adda_reg[2];
        addb_reg[3] <= addb_reg[2];
        result_reg[3] <= adda_reg[3] + addb_reg[3] + carry_in_reg[3][0];
        carry_in_reg[3][1] <= result_reg[3][64];
        o_en_reg[3] <= o_en_reg[2];
    end
end
// Pipeline stage 5
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[4] <= 64'd0;
        addb_reg[4] <= 64'd0;
        result_reg[4] <= 65'd0;
        carry_in_reg[4] <= 7'd0;
        o_en_reg[4] <= 1'b0;
    end else begin
        adda_reg[4] <= adda_reg[3];
        addb_reg[4] <= addb_reg[3];
        result_reg[4] <= adda_reg[4] + addb_reg[4] + carry_in_reg[4][0];
        carry_in_reg[4][1] <= result_reg[4][64];
        o_en_reg[4] <= o_en_reg[3];
    end
end
// Pipeline stage 6
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[5] <= 64'd0;
        addb_reg[5] <= 64'd0;
        result_reg[5] <= 65'd0;
        carry_in_reg[5] <= 7'd0;
        o_en_reg[5] <= 1'b0;
    end else begin
        adda_reg[5] <= adda_reg[4];
        addb_reg[5] <= addb_reg[4];
        result_reg[5] <= adda_reg[5] + addb_reg[5] + carry_in_reg[5][0];
        carry_in_reg[5][1] <= result_reg[5][64];
        o_en_reg[5] <= o_en_reg[4];
    end
end
// Pipeline stage 7
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[6] <= 64'd0;
        addb_reg[6] <= 64'd0;
        result_reg[6] <= 65'd0;
        carry_in_reg[6] <= 7'd0;
        o_en_reg[6] <= 1'b0;
    end else begin
        adda_reg[6] <= adda_reg[5];
        addb_reg[6] <= addb_reg[5];
        result_reg[6] <= adda_reg[6] + addb_reg[6] + carry_in_reg[6][0];
        carry_in_reg[6][1] <= result_reg[6][64];
        o_en_reg[6] <= o_en_reg[5];
    end
end
// Pipeline stage 8
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg[7] <= 64'd0;
        addb_reg[7] <= 64'd0;
        result_reg[7] <= 65'd0;
        carry_in_reg[7] <= 7'd0;
        o_en_reg[7] <= 1'b0;
    end else begin
        adda_reg[7] <= adda_reg[6];
        addb_reg[7] <= addb_reg[6];
        result_reg[7] <= adda_reg[7] + addb_reg[7] + carry_in_reg[7][0];
        carry_in_reg[7][1] <= result_reg[7][64];
        o_en_reg[7] <= o_en_reg[6];
    end
end
// Assign outputs
assign o_en = o_en_reg[7];
assign result = result_reg[7];
endmodule
